        "category": "AI 时代战略校准",
        "text": "评估自身业务是否依赖“易被复制的软件外壳”，规划好 N-1 上游 Token 供应链，思考“为 Agent 提供接口”或“用 Agent 交付服务”。",
        "detail": "在产品每 3 个月一迭代的高速期，以品牌信任、活数据/物理接口及真实服务能力构建护城河。",
        "refTalkId": "s4-yang-gang"
