        "slideText": "AIDSO 爱搜\n搜索流量演化\nSEO 传统搜索引擎优化\n58同城、链家、智联招聘 ...\nASO 应用商店优化\nboss直聘、美团、贝壳 ...\nDSO 超级App站内搜索（抖音、小红书、微信）\n剪映、懂车帝、住小帮 ...\nGEO 生成式引擎优化\n赋能AI时代头部公司\n2026 GEO 11月21日",
