        "slideText": "助听器的高维人群决策场景\n维度0到维度5：每加一维，问题更具体，需求越明确\n助听器高维场景人群\n维度0+产品词+品牌 — 助听器品牌\n维度1+产品词+品牌 — 适合儿童的助听器品牌推荐\n维度1+维度2+产品词+品牌 — 适合儿童长期佩戴的听器品牌有哪些\n维度1+维度2+维度3+产品词+品牌 — 适合3岁儿童长期佩戴的助听器品牌推荐\n维度1+维度2+维度3+维度4+产品词+品牌 — 适合3岁儿童长期佩戴的10000元左右的助听器品牌推荐\n维度1+维度2+维度3+维度4+维度5+产品词+品牌 — 适合3岁儿童长期佩戴的10000元左右的助听器品牌推荐，并且告诉我厦门哪里可以配？\n……更高维的场景拓展\n-TIPS- 问句生产不必追求大规模高维问句，而应确保词包覆盖既定场景维度；也不限于消费者实际检索的问题，但场景表达须匹配用户的搜索意图场景。GEO内容战略的实质，是向AI系统输入业务事实，依托语义匹配能力使AI自主识别需求并触达潜在客户，这与SEM、SEO依赖字面匹配的传统搜索营销逻辑存在本质区别。",
