        "caption": "苍何拆解「GEO核心逻辑：诊断->挖词->布词->推词->监测」五步闭环与平台矩阵（会场全景）",
        "slideText": "GEO核心逻辑：诊断->挖词->布词->推词->监测\n诊断 → 挖词（锁定目标）→ 内容一键创作 → 布词 → 内容自动分发 → 推词（饱和攻击）→ 监测\n挖词：通过精准挖掘高价值搜索词，识别目标客户真实需求｜核心关注：搜索量大+转化率高 + 激活AI任务｜原则：三高原则\n布词：将品牌产品信息巧妙植入AI可理解的内容中 AI喜欢 + AI相信 + AI推荐｜核心关注：知识库+结构化内容提升引用优先级｜原则：三化原则\n推词：通过自媒体+官方媒体矩阵进行全平台内容分发火力覆盖｜核心关注：信源+节奏+平台规则｜原则：三官一媒\nAI平台：豆包、元宝、DeepSeek、通义千问\n自媒体 + 官媒：搜狐、网易、新闻媒体、公众号、知乎、人民网、今日头条、凤凰网\nB → A → C",
